require dirname(__DIR__).'/includes/bootstrap.php';require_permission('drivers.verify');verify_csrf();$id=(int)($_POST['id']??0);if(!$id)redirect('drivers.php');try{transaction(function(PDO $pdo)use($id){$q=$pdo->prepare('SELECT status FROM drivers WHERE id=? FOR UPDATE');$q->execute([$id]);$old=$q->fetchColumn();if($old===false)throw new RuntimeException('Driver not found');$pdo->prepare("UPDATE drivers SET status='verified',verification_status='verified',verified_at=UTC_TIMESTAMP(),updated_by=? WHERE id=?")->execute([current_user_id(),$id]);$pdo->prepare('INSERT INTO driver_status_history(driver_id,from_status,to_status,reason,changed_by) VALUES(?,?,?,?,?)')->execute([$id,$old,'verified','Verified by authorized user',current_user_id()]);$pdo->prepare('UPDATE campaign_registrations SET counted=1,counted_at=COALESCE(counted_at,UTC_TIMESTAMP()) WHERE driver_id=?')->execute([$id]);audit('driver.verified','driver',$id);});flash('success','Driver verified and campaign progress recalculated.');}catch(Throwable $e){flash('error','Unable to verify this driver.');}redirect('drivers.php');
